const fs = require('fs');
const { createCanvas } = require('canvas');

const W = 1400, H = 2000;
const canvas = createCanvas(W, H);
const ctx = canvas.getContext('2d');

function roundRect(x,y,w,h,r,fill,stroke=null,sw=1){
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r);
  ctx.arcTo(x,y,x+w,y,r);
  ctx.closePath();
  if(fill){ctx.fillStyle=fill;ctx.fill();}
  if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=sw;ctx.stroke();}
}

const grad = ctx.createLinearGradient(0,0,0,H);
grad.addColorStop(0,'#071224');
grad.addColorStop(1,'#0A1E3A');
ctx.fillStyle = grad;
ctx.fillRect(0,0,W,H);

ctx.strokeStyle = '#0E2342';
ctx.lineWidth = 1;
for(let x=0;x<=W;x+=70){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
for(let y=0;y<=H;y+=70){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}

const colors = {text:'#EAF2FF',muted:'#9CB3D9',accent:'#35A7FF',green:'#43D17A',yellow:'#FFD166'};

ctx.fillStyle=colors.text; ctx.font='bold 72px sans-serif'; ctx.fillText('Open Source',70,120);
ctx.fillStyle=colors.accent; ctx.fillText('Contributor Index',70,205);
ctx.fillStyle=colors.green; ctx.font='bold 34px sans-serif'; ctx.fillText('MARCH 2026',70,258);
ctx.fillStyle=colors.muted; ctx.font='30px sans-serif'; ctx.fillText("Commercial organizations ranked by employees' GitHub open source activity",70,305);

roundRect(850,70,480,300,26,'#10294A','#1B4D86',2);
ctx.fillStyle=colors.yellow; ctx.font='bold 34px sans-serif'; ctx.fillText('#1 GOOGLE',878,125);
ctx.fillStyle=colors.text; ctx.font='bold 84px sans-serif'; ctx.fillText('548',878,225);
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('active contributors',1110,212);
ctx.fillStyle=colors.green; ctx.font='bold 36px sans-serif'; ctx.fillText('▲ +128 MoM',878,275);
ctx.fillStyle=colors.accent; ctx.font='25px sans-serif'; ctx.fillText('Total community: 1,986  ▲ +267',878,325);

roundRect(70,360,1260,920,24,'#0E203D','#1A3F70',2);
ctx.fillStyle=colors.text; ctx.font='bold 34px sans-serif'; ctx.fillText('TOP 10 CONTRIBUTING ORGANIZATIONS',96,415);

const cols = {rank:98, org:190, active:600, momA:840, comm:1000, momC:1230};
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif';
ctx.fillText('RANK',cols.rank,458); ctx.fillText('ORGANIZATION',cols.org,458); ctx.fillText('ACTIVE',cols.active,458);
ctx.fillText('Δ MoM',cols.momA,458); ctx.fillText('COMMUNITY',cols.comm,458); ctx.fillText('Δ MoM',cols.momC,458);

const data = [
[1,'Google',548,128,1986,267],[2,'Microsoft',438,74,1189,174],[3,'Red Hat',432,94,1378,193],[4,'AMD',233,66,627,109],[5,'Datadog',221,34,411,58],[6,'Intel',217,48,707,82],[7,'NVIDIA',194,41,650,106],[8,'SUSE',158,32,353,51],[9,'IBM',140,44,616,133],[10,'SAP',140,34,378,54]
];
let y0=485, rh=74;
data.forEach((r,i)=>{
  const y=y0+i*rh;
  if(i%2===0) roundRect(86,y-8,1228,rh-2,10,'#0C2547');
  if(r[0]===1) roundRect(84,y-10,1232,rh+2,10,null,'#2E8BFF',2);
  ctx.fillStyle = r[0]===1?colors.yellow:colors.text; ctx.font='bold 26px sans-serif'; ctx.fillText(String(r[0]),cols.rank,y+36);
  ctx.fillStyle = colors.text; ctx.font=r[0]===1?'bold 26px sans-serif':'25px sans-serif'; ctx.fillText(r[1],cols.org,y+36);
  ctx.font='bold 26px sans-serif'; ctx.fillText(r[2].toLocaleString(),cols.active,y+36);
  ctx.fillStyle=colors.green; ctx.fillText(`▲ +${r[3]}`,cols.momA,y+36);
  ctx.fillStyle=colors.text; ctx.fillText(r[4].toLocaleString(),cols.comm,y+36);
  ctx.fillStyle=colors.green; ctx.fillText(`▲ +${r[5]}`,cols.momC,y+36);
});

const py=1310, ph=610, gap=20, pw=Math.floor((W-140-2*gap)/3);
function panel(x,t){roundRect(x,py,pw,ph,20,'#0E203D','#1A3F70',2); ctx.fillStyle=colors.text; ctx.font='bold 34px sans-serif'; ctx.fillText(t,x+20,py+55);}

panel(70,'MONTHLY GROWTH MOMENTUM');
