ctx.fillStyle=colors.text; ctx.font='bold 58px sans-serif'; ctx.fillText('2,721',94,1460);
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('Net monthly increase',94,1515);
ctx.fillStyle=colors.green; ctx.font='bold 58px sans-serif'; ctx.fillText('▲ +595',94,1575);
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('All top 10 organizations posted',94,1642);
ctx.fillText('positive MoM growth in active',94,1672); ctx.fillText('contributors and community.',94,1702);
const pts=[[100,1830],[180,1810],[260,1800],[340,1765],[420,1740],[490,1695]];
ctx.strokeStyle=colors.green; ctx.lineWidth=4; ctx.beginPath(); ctx.moveTo(pts[0][0],pts[0][1]); for(let i=1;i<pts.length;i++) ctx.lineTo(pts[i][0],pts[i][1]); ctx.stroke();
pts.forEach(p=>{ctx.fillStyle=colors.green; ctx.beginPath(); ctx.arc(p[0],p[1],5,0,Math.PI*2); ctx.fill();});

const x2=70+pw+gap; panel(x2,'TOP PROGRAMMING LANGUAGES');
const langs=[['Python',20.3],['C++',14.3],['Go',11.6],['C',10.9],['TypeScript',10.5],['Java',4.4]];
langs.forEach((l,i)=>{ const y=1398+i*78; const bx=x2+24, bw=pw-48; ctx.fillStyle=colors.text; ctx.font='25px sans-serif'; ctx.fillText(l[0],bx,y); ctx.fillStyle=i===0?colors.accent:colors.muted; ctx.font='bold 26px sans-serif'; ctx.fillText(`${l[1].toFixed(1)}%`,bx+140,y); roundRect(bx,y+12,bw,20,9,'#14345D'); roundRect(bx,y+12,Math.floor(bw*(l[1]/22)),20,9,i===0?colors.accent:'#3E77B6'); });

const x3=70+2*(pw+gap); panel(x3,'ECOSYSTEM SCALE & LICENSING');
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('Organizations tracked',x3+24,1405);
ctx.fillStyle=colors.text; ctx.font='bold 58px sans-serif'; ctx.fillText('239',x3+24,1465);
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('Most common licenses',x3+24,1540);
['1  Apache-2.0','2  MIT','3  GPL-2.0','4  Other'].forEach((t,i)=>{ctx.fillStyle=i<2?colors.text:colors.muted; ctx.font='25px sans-serif'; ctx.fillText(t,x3+24,1585+i*46);});
ctx.fillStyle=colors.muted; ctx.font='21px sans-serif'; ctx.fillText('Key Signal',x3+24,1780);
ctx.fillStyle=colors.text; ctx.font='bold 36px sans-serif'; ctx.fillText('Google dominates while',x3+24,1820);
ctx.fillText('ecosystem participation',x3+24,1860);
ctx.fillStyle=colors.green; ctx.fillText('accelerates broadly.',x3+24,1900);

ctx.fillStyle='#7F99C2'; ctx.font='21px sans-serif'; ctx.fillText('Source: Open Source Contributor Index (OSCI) — March 2026 snapshot',70,1965);

fs.writeFileSync('/app/output/final_poster.png', canvas.toBuffer('image/png'));
console.log('/app/output/final_poster.png');
